/* ============================================================
 * 广告安装施工预约管理系统
 * 支持两种运行模式：
 *   - 云端模式(cloud)：配置 config.js 后，数据存 Supabase，多人实时同步
 *   - 本地模式(local)：未配置时，数据存浏览器 localStorage，单机使用
 * ============================================================ */

/* ----- PWA 安装：尽可能早地捕获 beforeinstallprompt 事件 -----
 * 某些浏览器在 DOMContentLoaded 之前就触发 beforeinstallprompt，
 * 如果监听挂得太晚就会错过事件，导致 deferredPrompt 永远为 null。
 * 这里在脚本最顶部立即挂监听，确保不会错过。
 */
window.__pwaDeferredPrompt = null;
window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  window.__pwaDeferredPrompt = e;
  // 通知 setupInstallPrompt（如果已初始化则直接用，否则后续初始化时会读取）
  window.dispatchEvent(new CustomEvent("__pwaPromptReady"));
});
window.addEventListener("appinstalled", () => {
  window.__pwaDeferredPrompt = null;
});

const STORE_KEY = "ad_install_system_v1";
const CUSTOMER_HISTORY_KEY = "ad_install_customer_history";
const DATA_VERSION = 2;
const MAX_LOGS = 1000;

// 工时合法范围（小时）：最低 0.1，最高 24。集中定义，避免散落字面量。
const HOURS_MIN = 0.1;
const HOURS_MAX = 24;
// 当日累计硬拦截上限：单日累计超过此值(18h)视为物理不可能/重复记工，直接阻止添加。
const DAILY_BLOCK_CAP = 18;
// 当日累计软上限：单日累计超过此值(12h)弹确认框（仍可加），提醒疑似重复。
const DAILY_WARN_CAP = 12;
// 点完工时「开工→完工」时长小于此分钟数，疑似未实际施工仅登记工时，给出警告（非拦截）。
const SHORT_WORK_WARN_MINUTES = 30;

// 每人每天标准工作量（小时）。用于「工时预警」与「施工人员安排」超限提醒。
const DAILY_WORK_HOURS = 8;
// 实际排班中加班常见，单日 10h 以内视为可接受；超过此值才做轻微提醒，避免误报。
// showWorkerSchedule 的对比行、时间线/日历的过载标记均以该值为触发阈值。
const DAILY_WORK_HOURS_WARN = 10;

function getCustomerHistory() {
  try {
    return JSON.parse(localStorage.getItem(CUSTOMER_HISTORY_KEY) || "[]");
  } catch {
    return [];
  }
}

function saveCustomerHistory(list) {
  lsSet(CUSTOMER_HISTORY_KEY, list.slice(0, 50));
}

function upsertCustomer(customer, phone, address) {
  if (!customer) return;
  const list = getCustomerHistory();
  const idx = list.findIndex(c => c.customer === customer);
  if (idx >= 0) {
    list[idx] = { customer, phone: phone || list[idx].phone, address: address || list[idx].address, updatedAt: Date.now() };
  } else {
    list.unshift({ customer, phone, address, updatedAt: Date.now() });
  }
  saveCustomerHistory(list);
}

function findCustomer(customer) {
  return getCustomerHistory().find(c => c.customer === customer) || null;
}

const STATUS = {
  BOOKED: "预约中",
  WORKING: "施工中",
  PAUSED: "已暂停",
  DELAYED: "已延期",
  DONE: "已完工",
  ACCEPTED: "已验收",
  REVIEWED: "已审核",
  CANCELLED: "已取消",
};

/*
 * 状态色唯一来源（单一事实来源）。
 * fg=文字/色条主色，bg=徽章浅底，border=徽章描边。
 * 以下三处全部从这里派生，禁止再手写十六进制：
 *   1) CSS 徽章 .badge.<状态> （运行时由 injectStatusBadgeStyles() 注入）
 *   2) 店面预约统计色条 SS_FG
 *   3) Excel 导出 statusColorMap
 */
const STATUS_COLOR = {
  '预约中': { fg: '#1d4ed8', bg: '#eef6ff', border: '#bfdbfe' },
  '施工中': { fg: '#b45309', bg: '#fffbeb', border: '#fde68a' },
  '已完工': { fg: '#15803d', bg: '#ecfdf5', border: '#86efac' },
  '已验收': { fg: '#5b21b6', bg: '#f5f3ff', border: '#c4b5fd' },
  '已审核': { fg: '#155e75', bg: '#ecfeff', border: '#99f6e4' },
  '已暂停': { fg: '#c2410c', bg: '#fff7ed', border: '#fed7aa' },
  '已延期': { fg: '#dc2626', bg: '#fef2f2', border: '#fca5a5' },
  '已取消': { fg: '#6b7280', bg: '#f9fafb', border: '#d1d5db' },
};
function statusHexToArgb(hex) { return 'FF' + hex.replace('#', '').toUpperCase(); }
// 运行时把状态色注入为 .badge.<状态> 规则，使 CSS 不再是独立来源
function injectStatusBadgeStyles() {
  const rules = Object.entries(STATUS_COLOR).map(([s, c]) =>
    `.badge.${s}{background:${c.bg};color:${c.fg};border:1px solid ${c.border};}`
  ).join('');
  let el = document.getElementById('status-badge-style');
  if (!el) {
    el = document.createElement('style');
    el.id = 'status-badge-style';
    document.head.appendChild(el);
  }
  el.textContent = rules;
}

